#include <Arduino.h>

// ESP32-C3 SuperMini
// Puente transparente USB <-> RN2903
//
// USB: 115200 baudios
// UART: 57600 baudios, 8N1
// GPIO0 = RX
// GPIO1 = TX

HardwareSerial LoRa(1);

void setup() {
  Serial.begin(115200);

  // UART1: RX = GPIO0, TX = GPIO1
  LoRa.begin(57600, SERIAL_8N1, 0, 1);

  delay(1000);
  Serial.println("Aqui estoy - Puente USB/UART activo");
}

void loop() {
  // USB -> RN2903
  while (Serial.available() > 0) {
    LoRa.write(Serial.read());
  }

  // RN2903 -> USB
  while (LoRa.available() > 0) {
    Serial.write(LoRa.read());
  }
}
